function initAboutImageDetails(){const pair=document.querySelector('.about-side-pair.is-about-scroll-pair');if(!pair)return;const details=[['01','International forum','A considered environment for ideas, people and meaningful exchange.'],['02','Live stage','A high-energy production shaped around the shared moment.'],['03','Digital summit','Connected experiences that bring audiences closer to the story.'],['04','Content world','Visual language and content designed to hold attention.'],['05','Business awards','A polished celebration built for recognition and impact.']];const panel=document.createElement('div');panel.className='about-image-detail';panel.setAttribute('aria-hidden','true');panel.innerHTML='<span class="about-image-detail-index"></span><strong></strong><p></p><a href="#contact">VIEW CASE <span>↗</span></a>';document.body.append(panel);let timer;const close=()=>{clearTimeout(timer);timer=setTimeout(()=>{panel.classList.remove('is-visible');panel.setAttribute('aria-hidden','true')},120)};[...pair.querySelectorAll('img')].forEach((image,index)=>{const open=event=>{clearTimeout(timer);const rect=image.getBoundingClientRect(),info=details[index];panel.querySelector('.about-image-detail-index').textContent=info[0];panel.querySelector('strong').textContent=info[1];panel.querySelector('p').textContent=info[2];panel.style.setProperty('--detail-x',`${Math.max(16,Math.min(innerWidth-286,rect.left+rect.width*.52))}px`);panel.style.setProperty('--detail-y',`${Math.max(16,Math.min(innerHeight-170,rect.top-170))}px`);panel.classList.add('is-visible');panel.setAttribute('aria-hidden','false');if(event)image.style.setProperty('--hover-scale','1.035')};image.addEventListener('pointerenter',open);image.addEventListener('pointerleave',()=>{image.style.removeProperty('--hover-scale');close()});image.addEventListener('focus',open);image.addEventListener('blur',close)})}
