function initCollageMotion(){const track=$('.reference-collage');if(!track||track.dataset.loopReady)return;track.dataset.loopReady='true';let offset=0,last=performance.now(),active=null,pointerPaused=false,focusPaused=false;const speed=.075;const syncPauseState=()=>track.classList.toggle('is-motion-paused',pointerPaused||focusPaused);track.addEventListener('pointerover',event=>{if(event.pointerType!=='touch'&&event.target.closest('img')){pointerPaused=true;syncPauseState()}});track.addEventListener('pointerout',event=>{if(event.pointerType==='touch')return;const next=event.relatedTarget;if(next instanceof Element&&next.closest('.reference-collage>img'))return;pointerPaused=false;syncPauseState()});track.addEventListener('focusin',event=>{if(event.target.closest('img')){focusPaused=true;syncPauseState()}});track.addEventListener('focusout',event=>{const next=event.relatedTarget;if(next instanceof Element&&next.closest('.reference-collage>img'))return;focusPaused=false;syncPauseState()});const tick=now=>{const elapsed=Math.min(80,now-last);last=now;const loopWidth=track.scrollWidth/2;if(loopWidth>0){if(!pointerPaused&&!focusPaused){offset-=elapsed*speed;if(offset<=-loopWidth)offset+=loopWidth}track.style.setProperty('transform',`translate3d(${offset}px,calc(1rem + 3cm),0)`,'important');const center=innerWidth/2;let closest=null,distance=Infinity;$$('.reference-collage img:not(.loop-copy)').forEach(card=>{const rect=card.getBoundingClientRect(),cardCenter=rect.left+rect.width/2,nextDistance=Math.abs(cardCenter-center);if(nextDistance<distance){distance=nextDistance;closest=card;}});if(closest!==active){active?.classList.remove('is-rail-active');closest?.classList.add('is-rail-active');active=closest;}}requestAnimationFrame(tick)};requestAnimationFrame(tick);}
