function initLuxuryCursor(){if(!matchMedia('(hover: hover) and (pointer: fine)').matches)return;const dot=document.createElement('span'),ring=document.createElement('span');dot.className='luxury-cursor-dot';ring.className='luxury-cursor-ring';document.body.append(dot,ring);document.body.classList.add('has-luxury-cursor');let targetX=innerWidth/2,targetY=innerHeight/2,x=targetX,y=targetY,lastX=targetX,lastY=targetY,velocity=0,angle=0;addEventListener('pointermove',event=>{targetX=event.clientX;targetY=event.clientY},{passive:true});const render=()=>{x+=(targetX-x)*.18;y+=(targetY-y)*.18;const dx=targetX-lastX,dy=targetY-lastY;velocity+=(Math.hypot(dx,dy)-velocity)*.16;lastX=targetX;lastY=targetY;angle+=(Math.atan2(dy,dx)*180/Math.PI-angle)*.12;const stretch=Math.min(1.45,1+velocity*.012);ring.style.transform=`translate3d(${x}px,${y}px,0) translate(-50%,-50%) rotate(${angle}deg) scale(${stretch},${1/stretch})`;dot.style.transform=`translate3d(${targetX}px,${targetY}px,0) translate(-50%,-50%)`;requestAnimationFrame(render)};render();}
function initProcessCursor(){if(!matchMedia('(hover: hover) and (pointer: fine)').matches||matchMedia('(prefers-reduced-motion: reduce)').matches)return;const section=document.querySelector('#dark-slide');if(!section)return;const orb=document.createElement('span');orb.className='process-cursor-orb';orb.setAttribute('aria-hidden','true');document.body.append(orb);let targetX=innerWidth*.82,targetY=innerHeight*.78,x=targetX,y=targetY,active=false;const move=event=>{targetX=event.clientX;targetY=event.clientY;section.style.setProperty('--process-pointer-x',`${event.clientX}px`);section.style.setProperty('--process-pointer-y',`${event.clientY}px`)};section.addEventListener('pointerenter',()=>{active=true;document.body.classList.add('process-cursor-active')});section.addEventListener('pointerleave',()=>{active=false;document.body.classList.remove('process-cursor-active')});section.addEventListener('pointermove',move,{passive:true});const render=()=>{x+=(targetX-x)*.12;y+=(targetY-y)*.12;orb.style.transform=`translate3d(${x}px,${y}px,0) translate(-50%,-50%)`;orb.style.setProperty('--orb-active',active?'1':'0');requestAnimationFrame(render)};render()}
function initCursorTrail(){if(!matchMedia('(hover: hover) and (pointer: fine) and (min-width: 701px)').matches||matchMedia('(prefers-reduced-motion: reduce)').matches)return;const canvas=document.createElement('canvas');canvas.className='luxury-cursor-trail';document.body.append(canvas);const ctx=canvas.getContext('2d');let width=0,height=0,dpr=1,mouseX=innerWidth/2,mouseY=innerHeight/2,lastX=mouseX,lastY=mouseY,emit=0,particles=[];const resize=()=>{dpr=Math.min(devicePixelRatio||1,2);width=innerWidth;height=innerHeight;canvas.width=width*dpr;canvas.height=height*dpr;canvas.style.width=`${width}px`;canvas.style.height=`${height}px`;ctx.setTransform(dpr,0,0,dpr,0,0)};const move=event=>{mouseX=event.clientX;mouseY=event.clientY};const spawn=(x,y,speed)=>{const count=Math.min(5,1+Math.floor(speed/12));for(let i=0;i<count;i++){const angle=Math.random()*Math.PI*2,force=.25+Math.random()*1.1;particles.push({x:x+(Math.random()-.5)*8,y:y+(Math.random()-.5)*8,vx:Math.cos(angle)*force,vy:Math.sin(angle)*force-.15,life:1,size:1+Math.random()*2.8,hue:Math.random()<.24?'#9b8cff':Math.random()<.52?'#d9f6ff':'#3e92ac'})}};const render=()=>{const dx=mouseX-lastX,dy=mouseY-lastY,speed=Math.hypot(dx,dy);lastX+=(mouseX-lastX)*.3;lastY+=(mouseY-lastY)*.3;emit+=speed;if(speed>.4){while(emit>6){spawn(lastX+(Math.random()-.5)*10,lastY+(Math.random()-.5)*10,speed);emit-=6}}ctx.clearRect(0,0,width,height);particles=particles.filter(p=>p.life>.02);particles.forEach(p=>{p.x+=p.vx;p.y+=p.vy;p.vx*=.985;p.vy=p.vy*.985+.006;p.life-=.018;ctx.globalAlpha=Math.max(0,p.life*.42);ctx.shadowBlur=14;ctx.shadowColor=p.hue;ctx.fillStyle=p.hue;ctx.beginPath();ctx.arc(p.x,p.y,p.size*p.life,0,Math.PI*2);ctx.fill()});ctx.globalAlpha=1;ctx.shadowBlur=0;requestAnimationFrame(render)};addEventListener('resize',resize,{passive:true});addEventListener('pointermove',move,{passive:true});resize();render();}
