function initExpertiseGallery(){const process=$('#process');if(!process||$('#expertise-gallery'))return;const section=document.createElement('section');section.id='expertise-gallery';section.className='expertise-gallery section-light';section.innerHTML='<div class="section-kicker"><span>05</span><span>Expertise</span></div><div class="expertise-gallery-head"><h2>Four disciplines.<br>One vision.</h2><p>The specialist crafts sit in the same room as the strategy, so nothing is lost between the idea and the event.</p></div><div class="expertise-tabs" role="tablist" aria-label="Expertise disciplines"></div><div class="expertise-gallery-body"><div class="expertise-copy"><span class="expertise-index">01</span><h3>Give the moment a reason.</h3><p>We begin with the story, the place and the audience, then shape a creative direction that answers what the occasion needs to say.</p><div class="expertise-list"><span>Creative strategy &amp; storytelling</span><span>Audience and occasion insight</span><span>Story architecture and show narrative</span></div></div><div class="expertise-media"><div class="expertise-card-stack"></div></div></div>';process.after(section);const tabs=section.querySelector('.expertise-tabs'),stack=section.querySelector('.expertise-card-stack'),items=[['Story','Give the moment a reason.','We begin with the story, the place and the audience, then shape a creative direction that answers what the occasion needs to say.','assets/event-show-01.png'],['Design','Make the idea tangible.','We turn the central idea into a considered visual and spatial language, from first sketch through every detail.','assets/premium-event-seating.png'],['Show','Bring the room to life.','We bring the experience to life through content, performance, production and the rhythm of the live moment.','assets/event-show-02.png'],['Delivery','Hold the moment perfectly.','We hold the moment with precision, care and the confidence to make every detail feel effortless.','assets/arab-business-meeting-4k.png']];let active=0;items.forEach((item,index)=>{const card=document.createElement('img');card.className='expertise-card';card.src=item[3];card.alt='Eventoria '+item[0]+' experience';card.dataset.index=index;stack.append(card)});const update=index=>{active=index;tabs.querySelectorAll('button').forEach((button,i)=>{button.classList.toggle('active',i===index);button.setAttribute('aria-selected',i===index)});stack.querySelectorAll('.expertise-card').forEach((card,i)=>card.classList.toggle('is-active',i===index));section.querySelector('.expertise-index').textContent='0'+(index+1);section.querySelector('h3').textContent=items[index][1];section.querySelector('.expertise-copy>p').textContent=items[index][2]};items.forEach((item,index)=>{const button=document.createElement('button');button.type='button';button.setAttribute('role','tab');button.textContent='0'+(index+1)+' / '+item[0];button.addEventListener('click',()=>update(index));tabs.append(button)});update(0);let ticking=false;addEventListener('scroll',()=>{if(ticking)return;ticking=true;requestAnimationFrame(()=>{const rect=section.getBoundingClientRect(),range=Math.max(1,section.offsetHeight-innerHeight),progress=Math.min(1,Math.max(0,-rect.top/range)),next=Math.min(items.length-1,Math.floor(progress*items.length));if(next!==active)update(next);ticking=false})},{passive:true});}
