function initCursorBackgroundResponse(){if(matchMedia('(prefers-reduced-motion: reduce)').matches)return;const sections=$$('main>section:not(#philosophy)');if(!sections.length)return;sections.forEach(section=>{if(section.querySelector(':scope > .cursor-bg-reactive'))return;const field=document.createElement('span');field.className='cursor-bg-reactive';field.setAttribute('aria-hidden','true');section.prepend(field);let targetX=50,targetY=50,currentX=50,currentY=50,raf=0;const render=()=>{currentX+=(targetX-currentX)*.075;currentY+=(targetY-currentY)*.075;const shiftX=(currentX-50)*-.12,shiftY=(currentY-50)*-.12,tiltX=(currentX-50)*.018,tiltY=(currentY-50)*-.012;section.style.setProperty('--bg-cursor-x',currentX.toFixed(2)+'%');section.style.setProperty('--bg-cursor-y',currentY.toFixed(2)+'%');section.style.setProperty('--bg-cursor-shift-x',shiftX.toFixed(2)+'px');section.style.setProperty('--bg-cursor-shift-y',shiftY.toFixed(2)+'px');section.style.setProperty('--bg-cursor-tilt-x',tiltX.toFixed(2)+'deg');section.style.setProperty('--bg-cursor-tilt-y',tiltY.toFixed(2)+'deg');if(Math.abs(targetX-currentX)>.02||Math.abs(targetY-currentY)>.02)raf=requestAnimationFrame(render);else raf=0};const move=event=>{const rect=section.getBoundingClientRect();targetX=Math.max(0,Math.min(100,((event.clientX-rect.left)/rect.width)*100));targetY=Math.max(0,Math.min(100,((event.clientY-rect.top)/rect.height)*100));section.classList.add('cursor-bg-active');if(!raf)raf=requestAnimationFrame(render)};const leave=()=>{targetX=50;targetY=50;section.classList.remove('cursor-bg-active');if(!raf)raf=requestAnimationFrame(render)};section.addEventListener('pointermove',move,{passive:true});section.addEventListener('pointerleave',leave,{passive:true});});}
