function initStorySlide(){const about=document.querySelector('#about');if(!about||document.querySelector('#story-approach'))return;const section=document.createElement('section');section.id='story-approach';section.className='story-approach section-light';section.innerHTML='<div class="section-kicker"><span>03</span><span>THE EVENTORIA APPROACH</span></div><div class="story-approach-grid"><div class="story-approach-media"><img src="assets/eventoria-banquet-concept-4k.png" alt="Eventoria event concept with guests and stage lighting"></div><div class="story-approach-copy"><h2>Every project<br>begins with a story.</h2><p>Every celebration begins somewhere quieter: a conversation, a question, a single line on paper. We listen for the story a moment is meant to tell, then draw, design, build and direct it through to the final show.</p><a href="#capabilities" class="story-approach-button">See the process <span>↗</span></a></div></div>';about.after(section);const media=section.querySelector('.story-approach-media'),copy=section.querySelector('.story-approach-copy');const update=()=>{const rect=section.getBoundingClientRect(),p=Math.max(0,Math.min(1,1-(rect.top-innerHeight*.18)/(innerHeight*.95)));section.style.setProperty('--story-progress',p.toFixed(3));media.style.setProperty('--story-media-y',`${(1-p)*70}px`);copy.style.setProperty('--story-copy-y',`${(1-p)*48}px`)};let ticking=false;addEventListener('scroll',()=>{if(ticking)return;ticking=true;requestAnimationFrame(()=>{update();ticking=false})},{passive:true});addEventListener('resize',update);update()}
