function applySlideHeadingHierarchy(){
  const replaceTag=(element,tagName)=>{if(!element||element.tagName.toLowerCase()===tagName)return element;const replacement=document.createElement(tagName);[...element.attributes].forEach(attribute=>replacement.setAttribute(attribute.name,attribute.value));while(element.firstChild)replacement.append(element.firstChild);element.replaceWith(replacement);return replacement};
  const mainHeadingSelectors=['#about .about-statement>h2','#story-approach .story-approach-copy>h2','#philosophy .philosophy-layout>h2','#work .work-heading>h2','#capabilities .cap-intro>h2','#process .process-heading>h2','#clients .clients-intro>h2','#contact .contact-heading>h2','#expertise-gallery .expertise-reference-top>h2'];
  mainHeadingSelectors.forEach(selector=>{const heading=replaceTag(document.querySelector(selector),'h1');if(heading)heading.dataset.slideHeading='primary'});
  document.querySelectorAll('#expertise-gallery .expertise-project-card').forEach(card=>{
    const title=replaceTag(card.querySelector('.expertise-project-info>h1'),'h1');
    const subheading=replaceTag(card.querySelector('.expertise-project-label'),'h2');
    if(title)title.dataset.slideHeading='primary';
    if(subheading)subheading.dataset.slideHeading='secondary';
  });
  document.querySelectorAll('#clients .client-card').forEach(card=>{
    const title=replaceTag(card.querySelector(':scope>h3'),'h2');
    const supportingHeading=replaceTag(card.querySelector(':scope>p'),'h3');
    if(title)title.dataset.cardHeading='primary';
    if(supportingHeading)supportingHeading.dataset.cardHeading='secondary';
  });
}
