function normalizeHeadingFullStops(){document.querySelectorAll('h1,h2,h3').forEach(heading=>{const walker=document.createTreeWalker(heading,NodeFilter.SHOW_TEXT);const nodes=[];while(walker.nextNode())nodes.push(walker.currentNode);nodes.forEach(node=>{if(!node.nodeValue.includes('.'))return;const fragment=document.createDocumentFragment();node.nodeValue.split(/(\.)/).forEach(part=>{if(part==='.') {const stop=document.createElement('span');stop.className='round-fullstop';stop.textContent='.';fragment.append(stop)}else if(part)fragment.append(document.createTextNode(part))});node.replaceWith(fragment)})})}
