function initClientRailDrag(){const rail=document.querySelector('#clients .client-cards');if(!rail)return;rail.scrollLeft=0;let down=false,startX=0,startScroll=0,snapTimer;const snapToPage=()=>{const pageWidth=rail.clientWidth;rail.scrollTo({left:Math.round(rail.scrollLeft/pageWidth)*pageWidth,behavior:'smooth'})};rail.addEventListener('wheel',event=>{if(Math.abs(event.deltaY)<Math.abs(event.deltaX))return;event.preventDefault();rail.scrollTo({left:rail.scrollLeft+(event.deltaY>0?pageWidth:-pageWidth),behavior:'smooth'})},{passive:false});rail.addEventListener('pointerdown',event=>{if(event.target.closest('.client-card')){down=true;startX=event.clientX;startScroll=rail.scrollLeft;rail.setPointerCapture?.(event.pointerId);rail.classList.add('is-dragging')}});rail.addEventListener('pointermove',event=>{if(!down)return;rail.scrollLeft=startScroll-(event.clientX-startX)});const end=event=>{down=false;rail.classList.remove('is-dragging');clearTimeout(snapTimer);snapTimer=setTimeout(snapToPage,80);try{rail.releasePointerCapture?.(event.pointerId)}catch{}};rail.addEventListener('pointerup',end);rail.addEventListener('pointercancel',end)}
