setTimeout(()=>{const brand=document.querySelector('.site-footer .footer-name-block');if(brand)brand.innerHTML=''},100);
setTimeout(()=>{document.querySelectorAll('.moments-photo').forEach(photo=>{if(photo.querySelector('.moments-instagram-icon'))return;const icon=document.createElement('img');icon.className='moments-instagram-icon';icon.src='assets/instagram-eventoria-icon-transparent.png';icon.alt='Instagram';photo.append(icon)})},450);
setTimeout(()=>{const stage=document.querySelector('#client-cards-slide .client-cards-stage');if(!stage||stage.dataset.marqueeReady)return;stage.dataset.marqueeReady='true';const names=['EMIRATES','COCA-COLA','SAMSUNG','MARRIOTT','GOOGLE','VISA','MICROSOFT','BMW','ADOBE','NIKE'];const slugs=['emirates','cocacola','samsung','marriott','google','visa','microsoft','bmw','adobe','nike'];const items=[...names,...names];stage.innerHTML='<div class="client-marquee-track">'+items.map((name,index)=>'<article class="client-marquee-card" aria-label="'+name+'" tabindex="0"><span>'+name+'</span><strong class="client-marquee-logo"><img src="https://cdn.simpleicons.org/'+slugs[index%slugs.length]+'/ffffff" alt="'+name+' logo"></strong><small>'+String((index%names.length)+1).padStart(2,'0')+'</small></article>').join('')+'</div>'},400);
setTimeout(()=>{document.querySelectorAll('.client-marquee-card').forEach(card=>{card.addEventListener('click',()=>{document.querySelectorAll('.client-marquee-card.is-focused').forEach(item=>{if(item!==card)item.classList.remove('is-focused')});card.classList.toggle('is-focused')})})},500);
setTimeout(()=>{const slide=document.querySelector('#dark-slide');if(!slide)return;slide.addEventListener('pointermove',event=>{const x=event.clientX/window.innerWidth*100,y=event.clientY/window.innerHeight*100;slide.style.setProperty('--wave-x',`${x}%`);slide.style.setProperty('--wave-y',`${y}%`);slide.style.setProperty('--wave-dx',`${(x-50)*.18}px`);slide.style.setProperty('--wave-dy',`${(y-50)*.18}px`)},{passive:true})},250);
setTimeout(()=>{document.querySelectorAll('.deliverable-card').forEach(card=>{card.addEventListener('pointerenter',()=>card.classList.add('is-selected'));card.addEventListener('pointerleave',()=>card.classList.remove('is-selected'));card.addEventListener('focusin',()=>card.classList.add('is-selected'));card.addEventListener('focusout',()=>card.classList.remove('is-selected'))})},350);
(()=>{const section=document.querySelector('#dark-slide'),frame=section?.closest('.dark-slide-scroll'),stack=section?.querySelector('.process-card-stack'),cards=stack?[...stack.querySelectorAll('.process-card')]:[];if(!frame||!stack||!cards.length)return;const update=()=>{const rect=frame.getBoundingClientRect(),progress=Math.max(0,Math.min(1,(innerHeight*.85-rect.top)/(innerHeight*.85)));stack.style.setProperty('--spread',progress.toFixed(3));cards.forEach(card=>card.style.setProperty('--card-spread',Math.max(0,Math.min(1,progress*3)).toFixed(3)))};addEventListener('scroll',()=>requestAnimationFrame(update),{passive:true});addEventListener('resize',update);update()})();
