setInterval(()=>{const section=document.querySelector('#dark-slide'),wrapper=section?.closest('.dark-slide-scroll');if(section){section.style.setProperty('background-image','none','important');section.style.setProperty('background-color','#fff','important');section.style.setProperty('color','#111','important');const intro=section.querySelector('.process-card-intro');intro?.style.setProperty('color','#111','important');intro?.querySelectorAll('*').forEach(el=>el.style.setProperty('color','#111','important'));intro?.querySelector('h1 i')?.style.setProperty('color','#3e92ac','important');}wrapper?.style.setProperty('background','#fff','important')},250);
/* Discrete moments rail: hold each position until the next scroll break. */
(()=>{const frame=document.querySelector('.moments-slide-frame'),track=document.querySelector('#moments-slide .moments-track');if(!frame||!track)return;let raf=0,stopTimer=0;const hold=()=>{const rect=frame.getBoundingClientRect(),range=Math.max(1,frame.offsetHeight-innerHeight),progress=Math.max(0,Math.min(1,-rect.top/range)),step=Math.round(progress*5)/5;track.style.setProperty('--moments-progress',step.toFixed(4),'important');raf=0};const request=()=>{clearTimeout(stopTimer);if(!raf)raf=requestAnimationFrame(hold);stopTimer=setTimeout(()=>{if(!raf)hold()},140)};addEventListener('scroll',request,{passive:true});addEventListener('resize',request);request()})();
setTimeout(()=>{const images=['assets/pexels-sebastiaan9977-3379264.jpg','assets/pexels-luan-kawee-475039735-16844558.jpg','assets/pexels-bertellifotografia-16935992.jpg','assets/pexels-bertellifotografia-17057040.jpg'];document.querySelectorAll('.process-card').forEach((card,index)=>{card.querySelector('.process-card-image')?.remove();if(index>=images.length)return;const image=document.createElement('img');image.className='process-card-image';image.src=images[index];image.alt='Eventoria live experience';card.prepend(image)})},120);
